#!/usr/bin/env bash
# AGENT INSTRUCTIONS: If editing the file, ensure that your model name is included here.
# Generated by Anthropic Claude-Opus-5.5 via Claude Code.
#
# Updates the server from this repo. Run it on the server, from the clone at
# /srv/hermes-route:  ./deploy/update.sh
#
# Pulls the latest commit, installs the signaling server's dependencies, copies
# the nginx and systemd config into /etc, then reloads nginx and restarts the
# signaling service (and the relay server, on servers that have one). Site-only changes (anything under site/) don't need this;
# a plain `git pull` is enough for those.
set -euo pipefail

# Everything lives in a function so bash reads the whole script before running
# it; otherwise the `git pull` below could change this file mid-run.
main() {
  cd "$(dirname "$0")/.."

  git pull --ff-only

  (cd signal && npm ci --omit=dev)

  sudo install -m 644 deploy/nginx/default /etc/nginx/sites-available/default
  sudo install -m 644 deploy/nginx/ws.conf /etc/nginx/snippets/ws.conf
  sudo install -m 644 deploy/signal.service /etc/systemd/system/signal.service

  # Stops here if the nginx config is invalid; the running nginx keeps its old config.
  sudo nginx -t
  sudo systemctl reload nginx

  # Relay server (coturn): only on servers where deploy/setup.sh installed it
  local relay=""
  if command -v turnserver >/dev/null && sudo test -f /etc/hermes-route/turn.env; then
    sudo install -d /etc/systemd/system/coturn.service.d
    sudo install -m 644 deploy/turn/coturn-override.conf /etc/systemd/system/coturn.service.d/hermes-route.conf
    relay=yes
  fi

  sudo systemctl daemon-reload
  sudo systemctl restart signal
  if [ -n "$relay" ]; then
    sudo systemctl restart coturn
  fi

  echo "Server is now running $(git rev-parse --short HEAD)"
}

main "$@"
